/*!  SapphireRWALibrary PROD v0.6.17 2026-07-17T11:15:56.751Z */
(function () {
	var DOCS = {"labelvalue":"<h6>Overview</h6>\n<p>A layout helper for form fields. It arranges a label, a control, and an optional hint into a consistent structure: the label sits beside or above the control, and the hint is rendered below the control inside the value area.</p>\n<p>The <code>LabelValue</code> helper does not own field logic or validation. It only handles presentation and accessibility: when the <code>Value</code> placeholder contains an input or checkbox with an <code>id</code>, the label text is wrapped in a <code>&lt;label for=&quot;…&quot;&gt;</code> so activating the label focuses the control.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>IsMandatory</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, appends a red asterisk (<code>*</code>) after the label text.</td>\n</tr>\n<tr>\n<td><code>LabelTopPadding</code></td>\n<td><code>Integer</code></td>\n<td>Top padding applied to the label in horizontal orientation, in pixels. Used to align the label with the control. Defaults to platform value.</td>\n</tr>\n<tr>\n<td><code>LabelWidth</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Fixed width of the label column when <code>Orientation</code> is <code>horizontal</code>. Ignored in vertical orientation.</td>\n</tr>\n<tr>\n<td><code>Orientation</code></td>\n<td><code>Text</code></td>\n<td>Layout direction: <code>horizontal</code> places the label and control side by side; <code>vertical</code> stacks the label above the control.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Hint</code></td>\n<td>Optional helper text shown below the control.</td>\n</tr>\n<tr>\n<td><code>Label</code></td>\n<td>Label text displayed next to or above the control.</td>\n</tr>\n<tr>\n<td><code>Value</code></td>\n<td>The form control or read-only content associated with the label.</td>\n</tr>\n</tbody></table>","actionpopup":"<h6>Overview</h6>\n<p>A modal action popup with a backdrop that blocks interaction with the page. It renders a title, a message, optional custom content (via the <code>Content</code> placeholder), a close button in the top-right corner, and up to three action buttons: Cancel, Negative and Positive.</p>\n<ul>\n<li>When a button label is &quot;&quot;, that button is not displayed.</li>\n<li>The Positive button always shows a <code>check-bold</code> icon before its label.</li>\n<li>Visibility is driven by the <code>IsOpen</code> input. On open, the dialog is teleported to <code>&lt;body&gt;</code>, page scroll is locked, focus moves into the dialog and Tab is trapped inside it.</li>\n<li>The close button (top-right) is only rendered when <code>HasClose</code> is <code>True</code>. The <code>Escape</code> key closes the popup only when <code>HasClose</code> AND <code>CloseOnEsc</code> are both <code>True</code>; when <code>HasClose</code> is <code>False</code> the popup can only be dismissed through the action buttons. Both the close button and <code>Escape</code> trigger the <code>Cancel</code> event. Clicking the backdrop never closes it.</li>\n<li>The Cancel / Negative / Positive buttons raise their respective events and then close the popup.</li>\n<li>The <code>Close</code> event fires whenever the popup closes, regardless of the trigger (any button, the close icon, <code>Escape</code>, or <code>IsOpen</code> being set to <code>False</code>). It is emitted after the specific button event.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>CloseOnEsc</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code> (and <code>HasClose</code> is <code>True</code>), pressing <code>Escape</code> closes the popup (fires <code>Cancel</code>).</td>\n</tr>\n<tr>\n<td><code>HasClose</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows the top-right close button. When <code>False</code>, hides it and disables the <code>Escape</code> shortcut, so the popup is only dismissible via the action buttons.</td>\n</tr>\n<tr>\n<td><code>IsOpen</code></td>\n<td><code>Boolean</code></td>\n<td>Controls visibility of the popup.</td>\n</tr>\n<tr>\n<td><code>LabelCancel</code></td>\n<td><code>Text</code></td>\n<td>Label on the cancel button. Button hidden when &quot;&quot;.</td>\n</tr>\n<tr>\n<td><code>LabelNo</code></td>\n<td><code>Text</code></td>\n<td>Label on the negative button. Button hidden when &quot;&quot;.</td>\n</tr>\n<tr>\n<td><code>LabelYes</code></td>\n<td><code>Text</code></td>\n<td>Label on the affirmative button. Button hidden when &quot;&quot;.</td>\n</tr>\n<tr>\n<td><code>Message</code></td>\n<td><code>Text</code></td>\n<td>Message of the popup. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>Padding</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireSize\"><code>SapphireSize</code></a></td>\n<td>Spacing preset for the dialog sections. Defaults to <code>m</code>.</td>\n</tr>\n<tr>\n<td><code>Title</code></td>\n<td><code>Text</code></td>\n<td>Title of the popup. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Spacing preset for the dialog width. Defaults to <code>m</code>.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Placeholder for custom content.</td>\n</tr>\n<tr>\n<td><code>Header</code></td>\n<td>Placeholder for custom content.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Toggle</code></td>\n<td>Fired when the component changes its state.</td>\n</tr>\n</tbody></table>","badge":"<h6>Overview</h6>\n<p>A compact status label for short text such as a category, state, or tag. It is a presentation-only component: color, optional leading status dot, and corner shape are driven by inputs; the label content comes from the <code>Content</code> placeholder.</p>\n<ul>\n<li>Default shape is a pill (<code>border-radius: 999px</code>). Use <code>Shape</code> to switch to rounded (<code>soft</code>) or square (<code>none</code>) corners.</li>\n<li>When <code>HasDot</code> is <code>True</code>, a small colored circle is rendered before the content, matching the selected <code>Color</code>.</li>\n<li>Color themes map to semantic surfaces: <code>neutral</code>, <code>info</code>, <code>success</code>, <code>warning</code>, and <code>error</code>.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Color</code></td>\n<td><code>SapphireColor</code></td>\n<td>Semantic color theme. Supported values: <code>neutral</code>, <code>info</code>, <code>success</code>, <code>warning</code>, <code>error</code>.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the badge visually / interactively as configured in the widget.</td>\n</tr>\n<tr>\n<td><code>HasDot</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows a leading status dot tinted to match <code>Color</code>.</td>\n</tr>\n<tr>\n<td><code>Shape</code></td>\n<td><code>Shape</code></td>\n<td>Corner style. Omit or leave default for a pill; <code>soft</code> uses a small radius; <code>none</code> removes rounding.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the badge container (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Text or markup displayed inside the badge.</td>\n</tr>\n</tbody></table>","buttondropdown":"<h6>Overview</h6>\n<p>A button that reveals a dropdown panel of actions. It supports two modes: a regular button whose label toggles the panel, and a split button where the label runs its own <code>Click</code> action while a dedicated chevron opens the panel.</p>\n<ul>\n<li>In regular mode the label is the trigger: activating it (click or <code>Enter</code>/<code>Space</code>, <code>ArrowDown</code> to open) toggles the panel.</li>\n<li>In split-button mode a chevron is appended after the label and becomes the trigger; the label instead fires the <code>Click</code> event.</li>\n<li>The panel closes when a menu action (link or button) is activated, on <code>Escape</code>, or on click outside. Form controls inside the panel do not close it.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ButtonClass</code></td>\n<td><code>Text</code></td>\n<td>Allows to style the button to the existing semantic versions.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables all interaction. Disabled dropdowns close any open panel.</td>\n</tr>\n<tr>\n<td><code>IsSplitButton</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, renders a separate chevron trigger and the label fires <code>Click</code> instead of opening.</td>\n</tr>\n<tr>\n<td><code>IsValid</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>False</code>, marks the component invalid and shows <code>ValidationMessage</code> below it.</td>\n</tr>\n<tr>\n<td><code>Placement</code></td>\n<td><code>Text</code></td>\n<td>Preferred placement of the actions panel relative to the trigger. Defaults to <code>bottom-start</code>.</td>\n</tr>\n<tr>\n<td><code>ValidationMessage</code></td>\n<td><code>Text</code></td>\n<td>Message shown below the widget while <code>IsValid</code> is <code>False</code>.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Sets the width of the component.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Label</code></td>\n<td>Element that acts as the button label / trigger.</td>\n</tr>\n<tr>\n<td><code>Actions</code></td>\n<td>Content of the dropdown panel (menu links or buttons).</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Click</code></td>\n<td>Fired when the label is activated in split-button mode (click or <code>Enter</code>/<code>Space</code>).</td>\n</tr>\n</tbody></table>","chip":"<h6>Overview</h6>\n<p>A compact, interactive element used to represent an attribute, filter, selection, or action. Chips can be clickable, selectable (toggle), and optionally include a leading icon and a clear button.</p>\n<p>The <code>Chip</code> enhances a root element containing a <code>.chip-content</code> node. Based on its configuration it wires up click, toggle, and clear interactions, reflects its state through <code>data-*</code> attributes, and manages the appropriate ARIA roles and keyboard support.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables all interaction. Disabled chips are not focusable.</td>\n</tr>\n<tr>\n<td><code>HasClear</code></td>\n<td><code>Boolean</code></td>\n<td>Renders a trailing clear button.</td>\n</tr>\n<tr>\n<td><code>Icon</code></td>\n<td><code>Text</code></td>\n<td>Optional leading icon name rendered before the content.</td>\n</tr>\n<tr>\n<td><code>IsClickable</code></td>\n<td><code>Boolean</code></td>\n<td>Makes the whole chip act as a button firing <code>Click</code>.</td>\n</tr>\n<tr>\n<td><code>IsSelectable</code></td>\n<td><code>Boolean</code></td>\n<td>Makes the chip a toggle that fires <code>Toggle</code> and tracks selected state.</td>\n</tr>\n<tr>\n<td><code>IsSelected</code></td>\n<td><code>Boolean</code></td>\n<td>Initial selected state (only meaningful when <code>IsSelectable</code>).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Element to be displayed as content.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Clear</code></td>\n<td>Fired when the clear button is activated.</td>\n</tr>\n<tr>\n<td><code>Click</code></td>\n<td>Fired when a clickable chip is activated (click or <code>Enter</code>/<code>Space</code>).</td>\n</tr>\n<tr>\n<td><code>Toggle</code></td>\n<td>Fired when a selectable chip is toggled; receives the new selected state.</td>\n</tr>\n</tbody></table>","overlay":"<h6>Overview</h6>\n<p>A floating overlay (popover / tooltip / dropdown surface) built on top of Tippy. It anchors content to a trigger element and handles positioning, focus management, keyboard navigation, RTL flipping, and optional iframe content.</p>\n<p>The <code>Overlay</code> attaches to a trigger element and shows a floating box containing either inline content, an external element, or an iframe. It supports click and hover triggers, persistent (manually dismissed) overlays, and full keyboard accessibility (Tab trapping, <code>Enter</code>/<code>Space</code> to toggle, <code>Escape</code> to close).</p>\n<p><a target=\"_blank\" href=\"https://atomiks.github.io/tippyjs/v6/all-props/#placement\">Tippy.js placement options</a></p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ExternalContentId</code></td>\n<td><code>Text</code></td>\n<td>Overrides the <code>Content</code> placeholder with an element defined elsewhere on the page.</td>\n</tr>\n<tr>\n<td><code>ExternalTriggerId</code></td>\n<td><code>Text</code></td>\n<td>Overrides the <code>Trigger</code> placeholder with an element defined elsewhere on the page.</td>\n</tr>\n<tr>\n<td><code>FocusOnClose</code></td>\n<td><code>Boolean</code></td>\n<td>Returns focus to the trigger when the overlay closes.</td>\n</tr>\n<tr>\n<td><code>FocusOnOpen</code></td>\n<td><code>Boolean</code></td>\n<td>Focuses the first focusable element when the overlay opens.</td>\n</tr>\n<tr>\n<td><code>Height</code></td>\n<td><code>Integer</code></td>\n<td>Fixed height in pixels.</td>\n</tr>\n<tr>\n<td><code>IframeURL</code></td>\n<td><code>Text</code></td>\n<td>Renders the overlay content inside an iframe pointing at this URL.</td>\n</tr>\n<tr>\n<td><code>MaxHeight</code></td>\n<td><code>Integer</code></td>\n<td>Maximum height in pixels.</td>\n</tr>\n<tr>\n<td><code>Options</code></td>\n<td><code>TippyTooltipOptions</code></td>\n<td>Tippy options controlling placement and behaviour. See the <code>Options</code> structure below.</td>\n</tr>\n<tr>\n<td><code>Padding</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireSize\"><code>SapphireSize</code></a></td>\n<td>Padding preset applied to the overlay box.</td>\n</tr>\n<tr>\n<td><code>Persistent</code></td>\n<td><code>Boolean</code></td>\n<td>Keeps the overlay open until explicitly closed and adds a close button.</td>\n</tr>\n<tr>\n<td><code>Theme</code></td>\n<td><code>Text</code></td>\n<td>Optional theme: <code>light</code>, <code>success</code>, <code>info</code>, <code>warning</code>, <code>error</code>. Include <code>disable-init</code> to skip auto-initialization, or <code>iframe-auto-size</code> to auto-size iframe content.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><code>Integer</code></td>\n<td>Fixed width in pixels (also raises <code>maxWidth</code> when larger).</td>\n</tr>\n</tbody></table>\n<hr><h6><code>TippyTooltipOptions</code> structure</h6>\n<p>Tippy configuration passed through to the underlying instance.</p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>placement</code></td>\n<td><code>Text</code></td>\n<td>Position of the overlay relative to the trigger (flipped automatically in RTL). See the Tippy placement link above.</td>\n</tr>\n<tr>\n<td><code>trigger</code></td>\n<td><code>Text</code></td>\n<td>Event(s) that open the overlay, e.g. <code>click</code> or <code>mouseenter focus</code>. Using <code>click</code> enables keyboard toggle.</td>\n</tr>\n<tr>\n<td><code>arrow</code></td>\n<td><code>Boolean</code></td>\n<td>Renders a pointer arrow on the overlay.</td>\n</tr>\n<tr>\n<td><code>delay</code></td>\n<td><code>Structure</code></td>\n<td>Show/hide delays in milliseconds: <code>{ Show, Hide }</code>.</td>\n</tr>\n<tr>\n<td><code>interactive</code></td>\n<td><code>Boolean</code></td>\n<td>Keeps the overlay open while the pointer is over its content.</td>\n</tr>\n<tr>\n<td><code>hideOnClick</code></td>\n<td><code>Boolean</code></td>\n<td>Hides the overlay when clicking outside it.</td>\n</tr>\n<tr>\n<td><code>flip</code></td>\n<td><code>Boolean</code></td>\n<td>Allows flipping to the opposite placement when there is no room. When <code>false</code>, flipping is disabled.</td>\n</tr>\n<tr>\n<td><code>maxWidth</code></td>\n<td><code>Integer</code></td>\n<td>Maximum width in pixels. Non-numeric values resolve to <code>none</code>; overridden by <code>Width</code> when <code>Width</code> is larger.</td>\n</tr>\n<tr>\n<td><code>appendTo</code></td>\n<td><code>Text</code></td>\n<td>Where the overlay is mounted. <code>body</code> appends to <code>&lt;body&gt;</code>; any other value mounts it next to the trigger.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Element to be displayed as content.</td>\n</tr>\n<tr>\n<td><code>Trigger</code></td>\n<td>Element to be used as the trigger.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Hide</code></td>\n<td>Fired when the overlay is hidden.</td>\n</tr>\n<tr>\n<td><code>Show</code></td>\n<td>Fired when the overlay becomes visible.</td>\n</tr>\n</tbody></table>","sapphiredropdown":"<h6>Overview</h6>\n<p>A combobox-style dropdown for selecting one or many options from a list. It supports search (client- or server-side), select-all, chips for selected values, clear, keyboard navigation / typeahead, and a validation message.</p>\n<ul>\n<li>The trigger is a focusable combobox; activating it (click or keyboard) opens a Tippy panel with the options listbox.</li>\n<li>Single select closes the panel after a choice. Multiple select keeps the panel open and toggles options; overflowing labels collapse to a count summary using <code>SelectedOptionsText</code>.</li>\n<li>When <code>Config.Search</code> is <code>True</code>, a search field filters options. Client-side search matches <code>Label</code> / <code>Description</code>; with <code>SearchServerSide</code>, typing emits <code>Search</code> (debounced 300ms) so the parent can refresh <code>OptionsList</code>.</li>\n<li>While <code>IsSearching</code> is <code>True</code>, the list is hidden and a loading spinner is shown (typical for server-side search).</li>\n<li>Scrolling the list near the bottom fires <code>ScrollEnded</code> once per reach (useful for paging more options).</li>\n<li>When <code>IsValid</code> is <code>False</code>, the trigger is marked invalid and <code>ValidationMessage</code> is shown below it.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Config</code></td>\n<td><code>SapphireDropdownConfig</code></td>\n<td>Behaviour and copy for the dropdown. See the structure below.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables interaction. Disabled dropdowns are not focusable / interactive.</td>\n</tr>\n<tr>\n<td><code>IsSearching</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows the loading state in the panel and hides the options list.</td>\n</tr>\n<tr>\n<td><code>IsValid</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>False</code>, marks the component invalid and shows <code>ValidationMessage</code>.</td>\n</tr>\n<tr>\n<td><code>OptionsList</code></td>\n<td><code>SapphireDropdownOption</code></td>\n<td>Available options to render in the list.</td>\n</tr>\n<tr>\n<td><code>SelectedList</code></td>\n<td><code>SapphireDropdownOption</code></td>\n<td>Currently selected options. Single-select keeps at most one entry; missing labels/icons are hydrated from <code>OptionsList</code> when possible.</td>\n</tr>\n<tr>\n<td><code>ValidationMessage</code></td>\n<td><code>Text</code></td>\n<td>Message shown below the trigger while <code>IsValid</code> is <code>False</code>.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the dropdown (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.). The open panel matches the trigger width.</td>\n</tr>\n</tbody></table>\n<hr><h6><code>SapphireDropdownOption</code> structure</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Description</code></td>\n<td><code>Text</code></td>\n<td>Optional secondary text under the label (shown when <code>ShowDescription</code>).</td>\n</tr>\n<tr>\n<td><code>Icon</code></td>\n<td><code>Text</code></td>\n<td>Optional icon name (shown when <code>ShowIcon</code>).</td>\n</tr>\n<tr>\n<td><code>Label</code></td>\n<td><code>Text</code></td>\n<td>Primary text shown in the list, trigger, and chips.</td>\n</tr>\n<tr>\n<td><code>Value</code></td>\n<td><code>Text</code></td>\n<td>Stable identifier for the option. Used for selection matching.</td>\n</tr>\n</tbody></table>\n<hr><h6><code>SapphireDropdownConfig</code> structure</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Clear</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows a clear control on the trigger while there is a selection.</td>\n</tr>\n<tr>\n<td><code>HasChips</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, renders selected options as clearable chips below the trigger.</td>\n</tr>\n<tr>\n<td><code>HasSelectAll</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code> and <code>Multiple</code> is <code>True</code>, adds a select-all row at the top of the list.</td>\n</tr>\n<tr>\n<td><code>Multiple</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, allows multiple selections; when <code>False</code>, selecting an option replaces the selection and closes the panel.</td>\n</tr>\n<tr>\n<td><code>Placeholder</code></td>\n<td><code>Text</code></td>\n<td>Trigger text when nothing is selected.</td>\n</tr>\n<tr>\n<td><code>Search</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows the search field in the panel.</td>\n</tr>\n<tr>\n<td><code>SearchServerSide</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, search emits <code>Search</code> for the parent to filter; when <code>False</code>, options are filtered locally.</td>\n</tr>\n<tr>\n<td><code>SearchKeyword</code></td>\n<td><code>Text</code></td>\n<td>Current search keyword (kept in sync with the search input).</td>\n</tr>\n<tr>\n<td><code>SearchPlaceholder</code></td>\n<td><code>Text</code></td>\n<td>Placeholder for the search input.</td>\n</tr>\n<tr>\n<td><code>ShowDescription</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, renders each option&#39;s <code>Description</code> when present.</td>\n</tr>\n<tr>\n<td><code>ShowIcon</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, renders each option&#39;s <code>Icon</code> when present (list, chips).</td>\n</tr>\n<tr>\n<td><code>NoOptionsText</code></td>\n<td><code>Text</code></td>\n<td>Empty-state message when there are no options.</td>\n</tr>\n<tr>\n<td><code>NoSearchResultsText</code></td>\n<td><code>Text</code></td>\n<td>Empty-state message when search yields no matches.</td>\n</tr>\n<tr>\n<td><code>SelectAllText</code></td>\n<td><code>Text</code></td>\n<td>Label for the select-all row.</td>\n</tr>\n<tr>\n<td><code>SelectedOptionsText</code></td>\n<td><code>Text</code></td>\n<td>Suffix used in the multi-select overflow summary, e.g. <code>&quot;3 selected&quot;</code> when labels do not fit.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Change</code></td>\n<td>Fired when the selection changes. Payload is a JSON string of the full <code>SelectedList</code> array (always an array, including single select).</td>\n</tr>\n<tr>\n<td><code>Clear</code></td>\n<td>Fired when the trigger clear control clears the entire selection (also followed by <code>Change</code>).</td>\n</tr>\n<tr>\n<td><code>ScrollEnded</code></td>\n<td>Fired when the options list is scrolled to (near) the bottom; resets when the user scrolls away from the end.</td>\n</tr>\n<tr>\n<td><code>SearchClear</code></td>\n<td>Fired when the search field is cleared.</td>\n</tr>\n<tr>\n<td><code>Search</code></td>\n<td>Fired (debounced) with the current keyword while searching; primarily used with <code>SearchServerSide</code>.</td>\n</tr>\n</tbody></table>","sapphireinput":"<h6>Overview</h6>\n<p>A text / numeric input with optional clear button, leading icon, validation message, and stepper controls. It masks and clamps values according to <code>Type</code> and <code>NumericOptions</code>, and can debounce <code>Change</code> while typing.</p>\n<ul>\n<li><code>Type</code> controls input behaviour: <code>text</code> (free text, start-aligned), <code>integer</code> (digits only), or <code>decimal</code> (digits plus a decimal part limited by <code>DecimalScale</code>).</li>\n<li>For numeric types, display uses a comma as the decimal separator; the internal / emitted value uses a dot.</li>\n<li>When <code>HasSteps</code> is <code>True</code> (numeric types), minus / plus controls appear and <code>ArrowUp</code> / <code>ArrowDown</code> step by <code>Step</code>, respecting <code>Min</code> / <code>Max</code>.</li>\n<li>When <code>HasClear</code> is <code>True</code> and the field has content, a clear control is shown; activating it fires <code>Clear</code> (the consumer typically clears <code>Value</code>).</li>\n<li>On blur (and after the debounce window), the value is remasked, clamped to <code>Min</code>/<code>Max</code>, and <code>Change</code> is emitted if it changed. <code>Enter</code> flushes any pending debounce, commits, then fires <code>EnterKey</code>.</li>\n<li>When <code>IsValid</code> is <code>False</code>, the field is marked invalid and <code>ValidationMessage</code> is shown below it. Externally set values outside type/bounds rules are flagged via <code>data-isoutofbounds</code> (red border) without rewriting the value.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>DebounceChange</code></td>\n<td><code>Integer</code></td>\n<td>Delay in milliseconds before <code>Change</code> fires while typing. <code>0</code> emits on every input. Blur / Enter always flush immediately.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables interaction. Disabled inputs ignore pointer events and use disabled styling.</td>\n</tr>\n<tr>\n<td><code>HasClear</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows a clear control while the field has content.</td>\n</tr>\n<tr>\n<td><code>HasSteps</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows minus / plus steppers (intended for numeric types) and enables arrow-key stepping.</td>\n</tr>\n<tr>\n<td><code>IconName</code></td>\n<td><code>Text</code></td>\n<td>Optional leading icon name. Empty string hides the icon and restores default start padding.</td>\n</tr>\n<tr>\n<td><code>IsValid</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>False</code>, marks the field invalid and shows <code>ValidationMessage</code>.</td>\n</tr>\n<tr>\n<td><code>MaxLength</code></td>\n<td><code>Integer</code></td>\n<td>Maximum character length. <code>0</code> (or less) means no limit. Applies to typing and truncates externally set values.</td>\n</tr>\n<tr>\n<td><code>NumericOptions</code></td>\n<td><code>SapphireInputNumericOptions</code></td>\n<td>Bounds and precision for numeric types. See the structure below. Ignored for <code>text</code>.</td>\n</tr>\n<tr>\n<td><code>Placeholder</code></td>\n<td><code>Text</code></td>\n<td>Placeholder text shown when the field is empty.</td>\n</tr>\n<tr>\n<td><code>Type</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireInputType\"><code>SapphireInputType</code></a></td>\n<td>Input mode: <code>text</code>, <code>integer</code>, or <code>decimal</code>.</td>\n</tr>\n<tr>\n<td><code>ValidationMessage</code></td>\n<td><code>Text</code></td>\n<td>Message shown below the field while <code>IsValid</code> is <code>False</code>.</td>\n</tr>\n<tr>\n<td><code>Value</code></td>\n<td><code>Text</code></td>\n<td>Current value. Numeric consumers should treat the emitted value as using <code>.</code> as the decimal separator.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the input container (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.).</td>\n</tr>\n</tbody></table>\n<hr><h6><code>SapphireInputNumericOptions</code> structure</h6>\n<p>Used when <code>Type</code> is <code>integer</code> or <code>decimal</code>. Empty / non-numeric <code>Min</code> or <code>Max</code> mean no bound.</p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>DecimalScale</code></td>\n<td><code>Integer</code></td>\n<td>Max digits after the decimal for <code>decimal</code> type. <code>0</code> (or with <code>integer</code>) disallows a fractional part.</td>\n</tr>\n<tr>\n<td><code>Max</code></td>\n<td><code>Text</code></td>\n<td>Upper bound. Empty means no maximum. Steppers and commit clamp to this value.</td>\n</tr>\n<tr>\n<td><code>Min</code></td>\n<td><code>Text</code></td>\n<td>Lower bound. Empty means no minimum. Steppers and commit clamp to this value.</td>\n</tr>\n<tr>\n<td><code>Step</code></td>\n<td><code>Decimal</code></td>\n<td>Amount added / subtracted by the steppers and <code>ArrowUp</code> / <code>ArrowDown</code>.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Hint</code></td>\n<td>Optional helper text rendered below the field (hidden when empty).</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Change</code></td>\n<td>Fired when the committed value changes (after debounce while typing, or immediately on blur / step).</td>\n</tr>\n<tr>\n<td><code>Clear</code></td>\n<td>Fired when the clear control is activated (click or <code>Enter</code>).</td>\n</tr>\n<tr>\n<td><code>EnterKey</code></td>\n<td>Fired when <code>Enter</code> is pressed, after any pending change has been flushed.</td>\n</tr>\n</tbody></table>","sapphirepopupcontent":"<h6>Overview</h6>\n<p>Structured content layout for the <strong>Popup</strong> widget from Service Studio. Use it when you need a dialog with a header, a scrollable body, an optional three-column footer, and an optional close button — without the built-in title, message, and action buttons of <code>ActionPopup</code>.</p>\n<ul>\n<li>The component renders a vertical flex layout: <strong>Header</strong> (fixed), <strong>Body</strong> (scrollable), and <strong>Footer</strong> (fixed, three columns).</li>\n<li>On initialization, focus moves into the popup content so keyboard users can interact immediately.</li>\n<li>The dialog is capped at <code>calc(100vh - 48px)</code>; when content exceeds that height, only the <strong>Body</strong> scrolls.</li>\n<li>Empty <strong>Header</strong> and <strong>Body</strong> placeholders are hidden. The <strong>Footer</strong> is hidden when all three footer placeholders are empty.</li>\n<li>When <code>HasClose</code> is <code>True</code>, a close button is shown in the top-right corner and the <strong>Header</strong> keeps a minimum height even when empty, so the close button does not overlap the body.</li>\n<li>When <code>HasSeparators</code> is <code>True</code>, horizontal separators are drawn between the header and body and between the body and footer.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>CloseOnEsc</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, pressing <code>Escape</code> fires the <code>Close</code> event.</td>\n</tr>\n<tr>\n<td><code>HasClose</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows the top-right close button and reserves header space for it. When <code>False</code>, the close button is hidden.</td>\n</tr>\n<tr>\n<td><code>HasSeparators</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, draws separators between the header/body and body/footer sections.</td>\n</tr>\n<tr>\n<td><code>Height</code></td>\n<td><code>Integer</code></td>\n<td>Fixed height of the popup content in pixels. When <code>0</code>, height grows with content (still limited by the viewport max-height).</td>\n</tr>\n<tr>\n<td><code>MinHeight</code></td>\n<td><code>Integer</code></td>\n<td>Minimum height of the popup content in pixels. When <code>0</code>, no minimum is applied.</td>\n</tr>\n<tr>\n<td><code>Padding</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireSize\"><code>SapphireSize</code></a></td>\n<td>Spacing preset for the dialog padding and section gaps. Supported values: <code>none</code>, <code>s</code>, <code>base</code>, <code>m</code>, <code>l</code>, <code>xl</code>.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the dialog. Supported values: <code>s</code> (400px), <code>m</code> (600px), <code>l</code> (960px, default), <code>xl</code> (1200px), <code>full</code> (viewport minus 48px).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Header</code></td>\n<td>Top section for a title or custom content. Rendered with heading-4 typography. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>Body</code></td>\n<td>Main scrollable content area. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>FooterLeft</code></td>\n<td>Left-aligned content in the footer grid (e.g. secondary actions).</td>\n</tr>\n<tr>\n<td><code>FooterCenter</code></td>\n<td>Center-aligned content in the footer grid.</td>\n</tr>\n<tr>\n<td><code>FooterRight</code></td>\n<td>Right-aligned content in the footer grid (e.g. primary actions).</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Close</code></td>\n<td>Fired when the close button is clicked or when <code>Escape</code> is pressed while <code>CloseOnEsc</code> is <code>True</code>.</td>\n</tr>\n</tbody></table>","scrollablecontent":"<h6>Overview</h6>\n<p>A vertical content layout with a fixed header, a scrollable body, and an optional three-column footer. Use it when you need a constrained-height region where only the body scrolls — for example inside overlays, side panels, or custom dialogs.</p>\n<ul>\n<li>The component renders a vertical flex layout: <strong>Header</strong> (fixed), <strong>Body</strong> (scrollable), and <strong>Footer</strong> (fixed, three columns).</li>\n<li><code>Height</code> and <code>MaxHeight</code> set the container size in pixels. When content exceeds the available height, only the <strong>Body</strong> scrolls.</li>\n<li>The body uses a thin scrollbar with a stable gutter so layout does not shift when the scrollbar appears.</li>\n<li>An empty <strong>Header</strong> is hidden. The <strong>Footer</strong> stays in the layout as a three-column grid (<code>FooterLeft</code> / <code>FooterCenter</code> / <code>FooterRight</code>).</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the component visually / interactively as configured in the widget.</td>\n</tr>\n<tr>\n<td><code>Height</code></td>\n<td><code>Text</code></td>\n<td>Fixed height of the container in pixels. When empty / unset, height is not forced and content can grow naturally.</td>\n</tr>\n<tr>\n<td><code>MaxHeight</code></td>\n<td><code>Integer</code></td>\n<td>Maximum height of the container in pixels. When <code>0</code>, no max-height is applied.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the container (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Header</code></td>\n<td>Top section for a title or custom content. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>Body</code></td>\n<td>Main scrollable content area. Grows to fill remaining space between header and footer.</td>\n</tr>\n<tr>\n<td><code>FooterLeft</code></td>\n<td>Left-aligned content in the footer grid (e.g. secondary actions).</td>\n</tr>\n<tr>\n<td><code>FooterCenter</code></td>\n<td>Center-aligned content in the footer grid.</td>\n</tr>\n<tr>\n<td><code>FooterRight</code></td>\n<td>Right-aligned content in the footer grid (e.g. primary actions).</td>\n</tr>\n</tbody></table>","sidebarwrapper":"<h6>Overview</h6>\n<p>This component is a wrapper for the Interaction\\Sidebar component from OSUI.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>HasOverlay</code></td>\n<td><code>Boolean</code></td>\n<td>Set to True, to show an overlay when the Sidebar is open. When you click on the overlay, the Sidebar is closed.</td>\n</tr>\n<tr>\n<td><code>IsOpen</code></td>\n<td><code>Boolean</code></td>\n<td>Controls visibility of the sidebar.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Spacing preset for the sidebar width. Defaults to <code>xl2</code>.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Placeholder for custom content.</td>\n</tr>\n<tr>\n<td><code>Header</code></td>\n<td>Placeholder for custom content.</td>\n</tr>\n</tbody></table>","skeleton":"<h6>Overview</h6>\n<p>A loading placeholder that shows animated skeleton shapes while data is being fetched, then reveals the real <code>Content</code> once loading completes. It can render any combination of a pulsing circle, a spinner, and a stack of bars, configured through the <code>Display</code> structure.</p>\n<p>While <code>IsWaiting</code> is <code>True</code> the placeholders pulse. When <code>IsWaiting</code> becomes <code>False</code>, each placeholder plays a staggered &quot;destruction&quot; animation and is removed; after the last one resolves, the <code>Content</code> placeholder is shown in its place. Placeholders render in a fixed order: circle, then spinner, then bars.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Display</code></td>\n<td><code>Structure</code></td>\n<td>Controls which loading placeholders are rendered. See the <code>Display</code> structure below.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the component.</td>\n</tr>\n<tr>\n<td><code>IsWaiting</code></td>\n<td><code>Boolean</code></td>\n<td>While <code>true</code>, placeholders are shown. Setting it to <code>false</code> animates them out and reveals <code>Content</code>.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Sets the width of the skeleton container.</td>\n</tr>\n</tbody></table>\n<hr><h6><code>Display</code> structure</h6>\n<p>An object describing which placeholders to render. Rendered in order: circle, loading, then bars.</p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Bars</code></td>\n<td><code>Integer</code></td>\n<td>Number of bar placeholders to render. When <code>&gt; 0</code>, renders that many bars with decreasing widths.</td>\n</tr>\n<tr>\n<td><code>Circle</code></td>\n<td><code>Text</code></td>\n<td>Size of a circular placeholder. Accepts <code>s</code>, <code>m</code>, or <code>l</code>; any other value (or empty) renders no circle.</td>\n</tr>\n<tr>\n<td><code>Loading</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>true</code>, renders a spinner loader.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Element to be displayed as content after IsWaiting becomes false.</td>\n</tr>\n</tbody></table>"};
	function normalize(name) {
		return String(name == null ? '' : name).toLowerCase().replace(/[^a-z0-9]/g, '');
	}
	function SapphireRWADocumentation(name) {
		if (!(this instanceof SapphireRWADocumentation)) return new SapphireRWADocumentation(name);
		this.name = name;
		this.html = DOCS[normalize(name)] || '';
	}
	SapphireRWADocumentation.has = function (name) { return normalize(name) in DOCS; };
	SapphireRWADocumentation.names = function () { return Object.keys(DOCS); };
	window.SapphireRWADocumentation = SapphireRWADocumentation;
})();
